"""Lexical scanner for jq source text."""

from dataclasses import dataclass
from enum import Enum, auto
import re

from .errors import CompileError


class TokenKind(Enum):
    IDENTIFIER = auto()
    NUMBER = auto()
    STRING = auto()
    FIELD = auto()
    BINDING = auto()
    FORMAT = auto()
    KEYWORD = auto()
    OPERATOR = auto()
    DELIMITER = auto()
    INTERPOLATION_START = auto()
    INTERPOLATION_END = auto()
    END = auto()
    IDENTITY = auto()


@dataclass(frozen=True)
class Token:
    kind: TokenKind
    text: str
    position: int


_KEYWORDS = {"as", "def", "module", "import", "include", "if", "then", "else", "elif", "and", "or", "end", "reduce", "foreach", "try", "catch", "label", "break"}
_OPERATORS = ("//=", "?//", "!=", "==", "|=", "+=", "-=", "*=", "/=", "%=", "<=", ">=", "..", "//")
_DELIMITERS = set(".?!=;,,:|+-*/%$<>{}[]()")
_NUMBER = re.compile(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")
_NAME = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
_QUALIFIED_NAME = re.compile(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*")


def _error(source: str, position: int, message: str) -> CompileError:
    line = source.count("\n", 0, position) + 1
    line_start = source.rfind("\n", 0, position) + 1
    return CompileError(f"{message} at line {line}, column {position - line_start + 1}")


def _scan_string(source: str, start: int) -> tuple[list[Token], int]:
    tokens = [Token(TokenKind.STRING, '"', start)]
    position = start + 1
    text_start = position
    while position < len(source):
        character = source[position]
        if character == "\\":
            if position + 1 >= len(source):
                raise _error(source, position, "unterminated string")
            if source[position + 1] == "(":
                if text_start < position:
                    tokens.append(Token(TokenKind.STRING, source[text_start:position], text_start))
                tokens.append(Token(TokenKind.INTERPOLATION_START, "\\(", position))
                expression_start = position + 2
                cursor = expression_start
                depth = 1
                quoted_expression = False
                escaped_expression = False
                while cursor < len(source):
                    current = source[cursor]
                    if quoted_expression:
                        if escaped_expression:
                            escaped_expression = False
                        elif current == "\\":
                            escaped_expression = True
                        elif current == '"':
                            quoted_expression = False
                    elif current == '"':
                        quoted_expression = True
                    elif current == "(":
                        depth += 1
                    elif current == ")":
                        depth -= 1
                        if depth == 0:
                            inner = tokenize(source[expression_start:cursor])
                            tokens.extend(inner[:-1])
                            tokens.append(Token(TokenKind.INTERPOLATION_END, ")", cursor))
                            position = cursor + 1
                            text_start = position
                            break
                    cursor += 1
                else:
                    raise _error(source, position, "unterminated interpolation")
                continue
            if source[position + 1] == "u":
                escape = source[position + 2:position + 6]
                if len(escape) != 4 or not re.fullmatch(r"[0-9A-Fa-f]{4}", escape):
                    raise _error(source, position, "invalid unicode escape")
                position += 6
            else:
                if source[position + 1] not in '"\\/bfnrt':
                    raise _error(source, position, "invalid escape")
                position += 2
            continue
        if character == '"':
            if text_start < position:
                tokens.append(Token(TokenKind.STRING, source[text_start:position], text_start))
            tokens.append(Token(TokenKind.STRING, '"', position))
            return tokens, position + 1
        if ord(character) < 0x20:
            raise _error(source, position, "control character in string")
        position += 1
    raise _error(source, start, "unterminated string")


def tokenize(source: str) -> list[Token]:
    """Tokenize jq source, retaining offsets and rejecting lexical errors."""
    tokens: list[Token] = []
    position = 0
    while position < len(source):
        character = source[position]
        if character.isspace():
            position += 1
            continue
        if character == "#":
            newline = source.find("\n", position)
            position = len(source) if newline < 0 else newline + 1
            continue
        if character == '"':
            string_tokens, position = _scan_string(source, position)
            tokens.extend(string_tokens)
            continue
        number = _NUMBER.match(source, position)
        if number:
            tokens.append(Token(TokenKind.NUMBER, number.group(), position))
            position = number.end()
            continue
        if character == "." and position + 1 < len(source) and source[position + 1].isalpha():
            name = _NAME.match(source, position + 1)
            assert name is not None
            tokens.append(Token(TokenKind.FIELD, source[position:name.end()], position))
            position = name.end()
            continue
        if character == "$":
            name = _QUALIFIED_NAME.match(source, position + 1)
            if not name:
                raise _error(source, position, "invalid binding")
            tokens.append(Token(TokenKind.BINDING, source[position:name.end()], position))
            position = name.end()
            continue
        if character == "@":
            name = _NAME.match(source, position + 1)
            if not name:
                raise _error(source, position, "invalid format")
            tokens.append(Token(TokenKind.FORMAT, source[position:name.end()], position))
            position = name.end()
            continue
        qualified = _QUALIFIED_NAME.match(source, position)
        if qualified:
            text = qualified.group()
            kind = TokenKind.KEYWORD if text in _KEYWORDS else TokenKind.IDENTIFIER
            tokens.append(Token(kind, text, position))
            position = qualified.end()
            continue
        operator = next((value for value in _OPERATORS if source.startswith(value, position)), None)
        if operator:
            tokens.append(Token(TokenKind.OPERATOR, operator, position))
            position += len(operator)
            continue
        if character in _DELIMITERS:
            kind = TokenKind.IDENTITY if character == "." else TokenKind.DELIMITER
            tokens.append(Token(kind, character, position))
            position += 1
            continue
        raise _error(source, position, "unexpected character")
    tokens.append(Token(TokenKind.END, "", len(source)))
    return tokens
"""Precedence-aware jq expression parser."""
import json
import re
from dataclasses import dataclass
from .ast import Filter, Node, StringTemplate, Format
from .errors import CompileError
from .lexer import tokenize

@dataclass(frozen=True)
class T: text: str
OPS=("//=","?//","!=","==","|=","+=","-=","*=","/=","%=","<=",">=","..","//")
# jq's query grammar gives the pipe lower precedence than comma.  This is
# significant for ``a | b, c``: it means ``a | (b, c)`` and keeps the input
# stream attached to both branches.  The parser's numeric levels increase
# with binding strength.
PREC={"|":1,",":2,"=":3,"|=":3,"+=":3,"-=":3,"*=":3,"/=":3,"%=":3,"//=":3,"//":4,"or":5,"and":6,"==":7,"!=":7,"<":7,">":7,"<=":7,">=":7,"+":8,"-":8,"*":9,"/":9,"%":9}

def lex(s: str) -> list[T]:
    s=re.sub(r"#[^\n]*","",s); out=[]; i=0
    while i<len(s):
        if s[i].isspace(): i+=1; continue
        if s[i]=='"':
            a=i; i+=1; esc=False
            while i<len(s):
                c=s[i]; i+=1
                if esc: esc=False
                elif c=='\\': esc=True
                elif c=='"': break
            else: raise CompileError("unterminated string")
            out.append(T(s[a:i])); continue
        op=next((x for x in OPS if s.startswith(x,i)),None)
        if op: out.append(T(op)); i+=len(op); continue
        m=re.match(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?",s[i:])
        if m: out.append(T(m.group())); i+=len(m.group()); continue
        m=re.match(r"(?:[A-Za-z_][A-Za-z_0-9]*::)*[A-Za-z_][A-Za-z_0-9]*",s[i:])
        if m: out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='$':
            m=re.match(r"\$[A-Za-z_][A-Za-z_0-9]*(?:::[A-Za-z_][A-Za-z_0-9]*)*",s[i:])
            if not m: raise CompileError("invalid binding")
            out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='.' and i+1<len(s) and re.match(r"[A-Za-z_]",s[i+1]):
            m=re.match(r"\.[A-Za-z_][A-Za-z_0-9]*",s[i:]); out.append(T(m.group())); i+=len(m.group()); continue
        if s[i]=='@':
            m=re.match(r"@[A-Za-z_][A-Za-z_0-9]*",s[i:])
            if not m: raise CompileError("invalid format")
            out.append(T(m.group())); i+=len(m.group()); continue
        if s[i] in ".?=;,:|+-*/%$<>()[]{}": out.append(T(s[i])); i+=1; continue
        raise CompileError("unexpected character")
    out.append(T("<eof>")); return out

class Parser:
    def __init__(self,s:str): self.t=lex(s); self.i=0
    def p(self): return self.t[self.i].text
    def take(self,x=None):
        v=self.p()
        if x is not None and v!=x: raise CompileError(f"expected {x}")
        self.i+=1; return v
    def parse(self):
        if self.p()=="<eof>": raise CompileError("empty program")
        x=self.expr(0)
        while self.p()==';': self.take()
        if self.p()!='<eof>': raise CompileError("unexpected token")
        return x
    def expr(self,n, stop_comma=False):
        x=self.prefix()
        # Binding is a query construct, below all ordinary operators.
        if self.p()=='as' and n <= 2:
            self.take('as'); pattern=self.pattern(); self.take('|')
            return Node('bind',(x,pattern,self.expr(0)))
        while (self.p() in PREC or self.p() in ('and','or')) and PREC.get(self.p(), 0)>=n:
            if stop_comma and self.p() == ',': break
            op=self.take(); q=PREC[op]; x=Node("binary",(op,x,self.expr(q if op in ("=","|=","+=","-=","*=","/=","%=","//=") else q+1, stop_comma)))
        if self.p()=='as' and n <= 2:
            self.take('as'); pattern=self.pattern(); self.take('|')
            return Node('bind',(x,pattern,self.expr(0)))
        return x
    def prefix(self):
        t=self.p()
        if t=='-':
            # Unary minus binds to the complete postfix term.  In particular
            # ``-.?`` is try-able arithmetic, not an optional identity.
            self.take(); return Node('unary',('-',self.prefix()))
        if t=='if': return self.post(self.if_expr())
        if t in ('try','reduce','foreach','label','break','def','module','import','include'): return self.post(self.control(t))
        if t=='(': self.take(); x=self.expr(0); self.take(')'); return self.post(x)
        if t=='[':
            self.take()
            if self.p()==']': x=Node('array',(None,))
            else:
                # Commas delimit array elements here; query commas inside an
                # element remain available through parentheses.
                parts=[self.expr(1, True)]
                while self.p()==',': self.take(); parts.append(self.expr(1, True))
                combined=parts[0]
                for part in parts[1:]: combined=Node('binary',(',',combined,part))
                # In an array, a trailing pipe belongs to the complete comma
                # query (`[a,b | f]` is `[(a,b) | f]`).
                if (combined.operation == 'binary' and combined.arguments[0] == ','
                        and combined.arguments[2].operation == 'binary'
                        and combined.arguments[2].arguments[0] == '|'
                        and combined.arguments[2].arguments[1].operation in ('unary', 'literal', 'binary')):
                    tail = combined.arguments[2]
                    combined = Node('binary', ('|', Node('binary', (',', combined.arguments[1], tail.arguments[1])), tail.arguments[2]))
                x=Node('array',(combined,))
            self.take(']'); return self.post(x)
        if t=='{': return self.object()
        if t=='.': self.take(); return self.post(Node('identity'))
        if t=='..': self.take(); return self.post(Node('recurse'))
        if t.startswith('.'): self.take(); return self.post(Node('field',(t[1:],)))
        if t.startswith('$'): self.take(); return self.post(Node('var',(t[1:],)))
        if t.startswith('"'): self.take(); return self.post(Node('string',(t,)))
        if t.startswith('@'): self.take(); return self.post(Node('format',(t[1:],)))
        self.take()
        if t in ('true','false','null','nan','infinite','-infinite','-nan') or re.fullmatch(r'(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?',t): return self.post(Node('literal',(t,)))
        return self.post(Node('call',(t,())))
    def post(self,x):
        while True:
            if self.p().startswith('"') and isinstance(x,Node) and x.operation=='format':
                x=Node('format_template',(x.arguments[0],self.take())); continue
            if self.p().startswith('"'):
                x=Node('indexexpr',(x,Node('string',(self.take(),)))); continue
            if self.p()=='?': self.take(); x=Node('optional',(x,)); continue
            if self.p().startswith('.') and len(self.p())>1: x=Node('index',(x,self.take()[1:],False)); continue
            if self.p()=='.' and self.t[self.i+1].text.startswith('"'):
                self.take('.'); x=Node('indexexpr',(x,Node('string',(self.take(),)))); continue
            if self.p()=='.' and self.t[self.i+1].text=='[':
                self.take('.'); continue
            if self.p()=='[':
                self.take()
                if self.p()==']': self.take(); x=Node('iterate',(x,)); continue
                a = Node('literal', ('null',)) if self.p()==':' else self.expr(0)
                if self.p()==':': self.take(); b=None if self.p()==']' else self.expr(0); self.take(']'); x=Node('slice',(x,a,b))
                else: self.take(']'); x=Node('indexexpr',(x,a))
                continue
            if self.p()=='(' and isinstance(x,Node) and x.operation=='call':
                name=x.arguments[0]; self.take(); args=[]
                if self.p()!=')':
                    args.append(self.expr(1))
                    # jq's grammar uses semicolons for filter arguments.  The
                    # corpus also exercises the permissive comma spelling.
                    while self.p()==';': self.take(); args.append(self.expr(1))
                self.take(')'); x=Node('call',(name,tuple(args))); continue
            break
        return x
    def object(self):
        self.take('{'); pairs=[]
        while self.p()!='}':
            if self.p()=='(':
                self.take('('); key=self.expr(0); self.take(')')
            else:
                k=self.take()
                if k.startswith('"'):
                    key=Node('string',(k,))
                elif k.startswith('$'):
                    key=Node('var',(k[1:],))
                else:
                    key=Node('string',(json.dumps(k.lstrip('$').lstrip('.')),))
            if self.p()==':': self.take(); v=self.expr(1, True)
            else:
                # `{name}` and `{$name}` abbreviate an access using the key.
                if k.startswith('"'):
                    # The key itself may be an interpolated jq string; keep
                    # it as a filter so decoding happens at evaluation time.
                    raw = None
                    v = Node('indexexpr',(Node('identity'), key))
                else:
                    raw = k.lstrip('$').lstrip('.')
                if k.startswith('$'):
                    key = Node('string',(json.dumps(raw),))
                    v=Node('var',(raw,))
                elif not k.startswith('"'):
                    v=Node('index',(Node('identity'),raw,False))
            if key.operation == 'literal':
                raise CompileError('object key must be a string')
            if key.operation == 'literal':
                raise CompileError('object key must be a string')
            pairs.append((key,v))
            if self.p()!= '}': self.take(',')
        self.take('}'); return Node('object',(tuple(pairs),))

    def pattern(self):
        t=self.p()
        if t.startswith('$'):
            result=Node('pattern_var',(self.take()[1:],))
            return self._pattern_alt(result)
        if t=='[':
            self.take()
            if self.p()==']': raise CompileError('empty destructuring pattern')
            items=[]
            if self.p()!=']':
                items.append(self.pattern())
                while self.p()==',': self.take(); items.append(self.pattern())
            self.take(']'); return self._pattern_alt(Node('pattern_array',(tuple(items),)))
        if t=='{':
            self.take()
            if self.p()=='}': raise CompileError('empty destructuring pattern')
            items=[]
            if self.p()!='}':
                while True:
                    if self.p() == '(':
                        self.take('('); key_node = self.expr(0); self.take(')')
                        if key_node.operation == 'literal':
                            raise CompileError('object key must be a string')
                        key = '<computed>'
                    else:
                        key=self.take(); key_node = None
                        if key.startswith('"'): key = json.loads(key)
                    if self.p()==':':
                        self.take(); pat=self.pattern()
                        if key.startswith('$'):
                            pat = Node('pattern_bind',(key[1:],pat))
                    elif key.startswith('$'): pat=Node('pattern_var',(key[1:],))
                    else: pat=Node('pattern_var',(key,))
                    items.append((key_node if key_node is not None else key.lstrip('$'),pat))
                    if self.p()!='}': self.take(',')
                    else: break
            self.take('}'); return self._pattern_alt(Node('pattern_object',(tuple(items),)))
        raise CompileError('expected binding pattern')

    def _pattern_alt(self, result):
        if self.p()=='?//':
            self.take('?//'); return Node('pattern_alt',(result,self.pattern()))
        return result
    def if_expr(self):
        self.take('if'); c=self.expr(0); self.take('then'); a=self.expr(0); b=Node('literal',('null',))
        if self.p()=='else': self.take(); b=self.expr(0); self.take('end')
        elif self.p()=='elif':
            b=self._elif_expr()
        else: self.take('end'); b=Node('identity')
        return Node('if',(c,a,b))
    def _elif_expr(self):
        self.take('elif'); c=self.expr(0); self.take('then'); a=self.expr(0)
        if self.p()=='elif': b=self._elif_expr()
        elif self.p()=='else': self.take(); b=self.expr(0); self.take('end')
        else: self.take('end'); b=Node('identity')
        return Node('if',(c,a,b))
    def control(self,w):
        self.take(w)
        if w in ('module', 'import', 'include'):
            raise CompileError('module directives are not available')
        if w=='try':
            # In object values the following comma belongs to the object,
            # while the try/catch body still admits the full query pipe.
            # `try` binds more tightly than defined-or and comma.  Its
            # optional catch clause is consequently visible to this control
            # production rather than being swallowed by the protected query.
            a=self.expr(10, True); b=None
            if self.p()=='catch': self.take(); b=self.expr(10, True)
            return Node('try',(a,b))
        if w=='def':
            name=self.take(); ps=[]
            if self.p()=='(': self.take();
            while self.p() not in (')',':'):
                # Preserve the sigil: ``f(x)`` receives a filter, while
                # ``f($x)`` receives the values produced by its argument.
                ps.append(self.take())
                if self.p()==';': self.take()
            if ps: self.take(')')
            self.take(':'); b=self.expr(0); self.take(';')
            definition=Node('def',(name,tuple(ps),b))

"""Ordered generator evaluator boundary."""
import json
import math
import datetime
import itertools
import sys
from functools import cmp_to_key

from .ast import Add, Array, Comma, Filter, Format, Identity, Iterate, Literal, Limit, Node, Pipe, Raise, StringTemplate
from .errors import FLOW_RUNTIME_ERRORS, RuntimeError
from .runtime import InputNumber, JsonValue, ValueStream, identity_stream


class _OverflowFloat(float):
    """A parsed exponent overflow that jq still emits as a JSON number."""

    pass


def evaluate(program: Filter, value: JsonValue) -> ValueStream:
    """Evaluate one input as an ordered stream of output values."""
    if isinstance(program, Node):
        yield from _node(program, value, {})
        return
    if isinstance(program, Identity):
        yield from identity_stream(value)
        return
    if isinstance(program, Iterate):
        yield from _iter_values(value)
        return
    if isinstance(program, Literal):
        yield program.value
        return
    if isinstance(program, Pipe):
        for intermediate in evaluate(program.left, value): yield from evaluate(program.right, intermediate)
        return
    if isinstance(program, Add):
        left = list(evaluate(program.left, value))
        right = list(evaluate(program.right, value))
        for first in left:
            for second in right:
                if isinstance(first, (int, float)) and isinstance(second, (int, float)):
                    yield first + second
                elif isinstance(first, str) and isinstance(second, str): yield first + second
                elif first is None: yield second
                elif second is None: yield first
                else: raise RuntimeError("cannot add values")
        return
    if isinstance(program, StringTemplate):
        pieces: list[str] = []
        for part in program.parts:
            pieces.append(part if isinstance(part, str) else "".join(_stringify(x) for x in evaluate(part, value)))
        yield "".join(pieces)
        return
    if isinstance(program, Format):
        if program.template is None: yield _apply_format(program.name, value)
        else:
            pieces: list[str] = []
            for part in program.template.parts:
                if isinstance(part, str): pieces.append(part)
                else:
                    pieces.extend(_apply_format(program.name, item) for item in evaluate(part, value))
            yield "".join(pieces)
        return
    if isinstance(program, Comma):
        yield from evaluate(program.left, value)
        yield from evaluate(program.right, value)
        return
    if isinstance(program, Raise):
        raise RuntimeError(program.message)
    if isinstance(program, Array):
        yield list(evaluate(program.expression, value))
        return
    if isinstance(program, Limit):
        outputs = iter(evaluate(program.expression, value))
        for _ in range(program.count):
            try:
                yield next(outputs)
            except StopIteration:
                break
        return
    raise RuntimeError("unknown compiled filter")

def _node(node: Node, value: object, env: dict[str, object]) -> ValueStream:
    op, a = node.operation, node.arguments
    if op == "identity": yield value
    elif op == "literal":
        text=a[0]; special={"true":True,"false":False,"null":None,"nan":float("nan"),"infinite":float("inf"),"-infinite":float("-inf"),"-nan":float("nan")}
        if text in special:
            yield special[text]
        else:
            parsed = json.loads(text)
            if isinstance(parsed, int) and abs(parsed) > 2**53:
                parsed = float(parsed)
            if isinstance(parsed, float) and math.isinf(parsed):
                parsed = _OverflowFloat(parsed)
            yield parsed
    elif op == "string": yield _decode_string(a[0], value, env)
    elif op == "format": yield _apply_format(a[0], value)
    elif op == "format_template":
        # Interpolation is evaluated first; the formatter consumes the
        # resulting string (not the original input value).
        yield _apply_format(a[0], _decode_string(a[1], value, env))
    elif op == "var":
        if a[0] == '__loc__':
            yield {'file': '<top-level>', 'line': 1}
            return
        if a[0] in env and not isinstance(env[a[0]], tuple):
            bound = env[a[0]]
            if isinstance(bound, Node): yield from _node(bound, value, env)
            else: yield bound
            return
        if a[0] in env.get('__params__', {}):
            captured, argument = env['__params__'][a[0]]
            yield from _node(argument, value, captured)
            return
        if a[0] not in env: raise RuntimeError(f"variable ${a[0]} is not defined")
        bound = env[a[0]]
        if isinstance(bound, tuple) and bound and bound[0] == '__closure__':
            yield from _node(bound[1], value, {**env, **bound[2]})
        elif isinstance(bound, Node):
            yield from _node(bound, value, env)
        else:
            yield bound
    elif op == "bind":
        for item in _node(a[0], value, env):
            # A destructuring alternative is a speculative binding: jq must
            # retry the next pattern when either matching or the continuation
            # fails.  Keeping the continuation inside this loop is important;
